### 1.2 Semantic Token Bindings (`src/styles/tokens/_system.scss`)

```scss
@use 'reference' as ref;

@mixin root-light-tokens {
  // Color - Surface & Background
  --md-sys-color-background: #{map-get(ref.$md-ref-palette-neutral, 98)};
  --md-sys-color-on-background: #{map-get(ref.$md-ref-palette-neutral, 10)};
  --md-sys-color-surface: #{map-get(ref.$md-ref-palette-neutral, 98)};
  --md-sys-color-on-surface: #{map-get(ref.$md-ref-palette-neutral, 10)};
  --md-sys-color-surface-container: #{map-get(ref.$md-ref-palette-neutral, 95)};
  --md-sys-color-surface-container-high: #{map-get(ref.$md-ref-palette-neutral, 90)};

  // Color - Primary (Tone 40 Base)
  --md-sys-color-primary: #{map-get(ref.$md-ref-palette-primary, 40)};
  --md-sys-color-on-primary: #{map-get(ref.$md-ref-palette-primary, 100)};
  --md-sys-color-primary-container: #{map-get(ref.$md-ref-palette-primary, 90)};
  --md-sys-color-on-primary-container: #{map-get(ref.$md-ref-palette-primary, 10)};

