### 3.1 Theme Controller (`src/core/theme/ThemeEngine.ts`)

```typescript
export type ThemeMode = 'light' | 'dark' | 'system';

export class ThemeEngine {
  private static readonly STORAGE_KEY = 'app_theme_preference';
  private mediaQueryList: MediaQueryList;

  constructor() {
    this.mediaQueryList = window.matchMedia('(prefers-color-scheme: dark)');
    this.init();
  }

  public init(): void {
    const savedTheme = (localStorage.getItem(ThemeEngine.STORAGE_KEY) as ThemeMode) || 'system';
    this.applyTheme(savedTheme);

    this.mediaQueryList.addEventListener('change', (e) => {
      if (this.getStoredPreference() === 'system') {
        this.setDocumentTheme(e.matches ? 'dark' : 'light');
      }
    });
  }

  public applyTheme(mode: ThemeMode): void {
    localStorage.setItem(ThemeEngine.STORAGE_KEY, mode);

    if (mode === 'system') {
      const isDark = this.mediaQueryList.matches;
      this.setDocumentTheme(isDark ? 'dark' : 'light');
    } else {
      this.setDocumentTheme(mode);
    }
  }

  public getStoredPreference(): ThemeMode {
    return (localStorage.getItem(ThemeEngine.STORAGE_KEY) as ThemeMode) || 'system';
  }

  private setDocumentTheme(resolvedTheme: 'light' | 'dark'): void {
    document.documentElement.setAttribute('data-theme', resolvedTheme);
  }
}
