### 4.1 Contrast Calculation & WCAG AA Automation Test (`tests/unit/tokens/ContrastValidator.spec.ts`)

```typescript
import { describe, it, expect } from 'vitest';

/**
 * Calculates relative luminance as defined by W3C WCAG 2.1
 * Formula: https://www.w3.org/WAI/GL/wiki/Relative_luminance
 */
function getRelativeLuminance(hexColor: string): number {
  const hex = hexColor.replace('#', '');
  const r = parseInt(hex.substring(0, 2), 16) / 255;
  const g = parseInt(hex.substring(2, 4), 16) / 255;
  const b = parseInt(hex.substring(4, 6), 16) / 255;

  const [rL, gL, bL] = [r, g, b].map((val) => {
    return val <= 0.03928 ? val / 12.92 : Math.pow((val + 0.055) / 1.055, 2.4);
  });

  return 0.2126 * rL + 0.7152 * gL + 0.0722 * bL;
}

function calculateContrastRatio(foreground: string, background: string): number {
  const l1 = getRelativeLuminance(foreground);
  const l2 = getRelativeLuminance(background);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

describe('M3 Tokens: WCAG 2.1 AA Contrast Compliance', () => {
  describe('Dark Theme Token Assertions', () => {
    const darkBackground = '#141218'; // Neutral 10
    const darkPrimaryTone80 = '#9ecafd'; // Primary Tone 80 Fallback
    const darkOnPrimary = '#00315b'; // Primary Tone 20
    const darkOnBackground = '#e6e1e5'; // Neutral 90

    it('FR-1 / NFR-2: High-luminance Tone 80 Primary must exceed 4.5:1 against Dark Background', () => {
      const ratio = calculateContrastRatio(darkPrimaryTone80, darkBackground);
      expect(ratio).toBeGreaterThanOrEqual(4.5);
      expect(parseFloat(ratio.toFixed(2))).toBeGreaterThanOrEqual(7.5); // Expected ~8.1:1
    });

    it('FR-1 / NFR-2: On-Primary text on Primary Container/Button must exceed 4.5:1', () => {
      const ratio = calculateContrastRatio(darkOnPrimary, darkPrimaryTone80);
      expect(ratio).toBeGreaterThanOrEqual(4.5);
    });

    it('FR-1 / NFR-2: On-Background content must exceed 4.5:1 against Dark Background', () => {
      const ratio = calculateContrastRatio(darkOnBackground, darkBackground);
      expect(ratio).toBeGreaterThanOrEqual(4.5);
    });
  });

  describe('Light Theme Token Assertions', () => {
    const lightBackground = '#fef7ff'; // Neutral 98
    const lightPrimaryTone40 = '#1a5f9c'; // Primary Tone 40
    const lightOnPrimary = '#ffffff'; // Tone 100

    it('Light Primary Tone 40 must exceed 4.5:1 against Light Background', () => {
      const ratio = calculateContrastRatio(lightPrimaryTone40, lightBackground);
      expect(ratio).toBeGreaterThanOrEqual(4.5);
    });

    it('Light On-Primary (White) must exceed 4.5:1 against Light Primary Tone 40', () => {
      const ratio = calculateContrastRatio(lightOnPrimary, lightPrimaryTone40);
      expect(ratio).toBeGreaterThanOrEqual(4.5);
    });
  });
});
