package com.platform.account.domain;

import java.time.Instant;
import java.util.Optional;

public class Account {
    private final String id;
    private final Status status;
    private final String displayName;
    private final Instant updatedAt;

    public enum Status {
        ACTIVE,
        INACTIVE
    }

    public Account(String id, Status status, String displayName, Instant updatedAt) {
        this.id = id;
        this.status = status;
        this.displayName = displayName;
        this.updatedAt = updatedAt;
    }

    public String getId() { return id; }
    public Status getStatus() { return status; }
    public String getDisplayName() { return displayName; }
    public Instant getUpdatedAt() { return updatedAt; }

    public Account copyWith(Optional<Status> newStatus, Optional<String> newDisplayName) {
        return new Account(
            this.id,
            newStatus.orElse(this.status),
            newDisplayName.orElse(this.displayName),
            Instant.now()
        );
    }
}
