### 3. Mapper Layer

```java
package com.platform.account.mapper;

import com.platform.account.domain.Account;
import com.platform.account.v1.AccountResponse;
import com.platform.account.v1.AccountStatus;
import com.platform.account.v1.UpdateAccountRequest;

import java.util.Optional;

public class AccountMapper {

    public static Optional<Account.Status> toDomainStatus(UpdateAccountRequest request) {
        if (!request.hasStatus()) {
            return Optional.empty();
        }
        AccountStatus protoStatus = request.getStatus();
        return switch (protoStatus) {
            case ACTIVE -> Optional.of(Account.Status.ACTIVE);
            case INACTIVE -> Optional.of(Account.Status.INACTIVE);
            case ACCOUNT_STATUS_UNSPECIFIED, UNRECOGNIZED -> 
                throw new IllegalArgumentException("Invalid status provided: " + protoStatus);
        };
    }

    public static Optional<String> toDomainDisplayName(UpdateAccountRequest request) {
        return request.hasDisplayName() ? Optional.of(request.getDisplayName()) : Optional.empty();
    }

    public static AccountResponse toProtoResponse(Account account) {
        AccountStatus status = switch (account.getStatus()) {
            case ACTIVE -> AccountStatus.ACTIVE;
            case INACTIVE -> AccountStatus.INACTIVE;
        };

        return AccountResponse.newBuilder()
            .setAccountId(account.getId())
            .setStatus(status)
            .setDisplayName(account.getDisplayName())
            .setUpdatedAt(account.getUpdatedAt().toEpochMilli())
            .build();
    }
}
