### 5. Service Implementation

```java
package com.platform.account.service;

import com.platform.account.domain.Account;
import com.platform.account.domain.AccountRepository;
import com.platform.account.mapper.AccountMapper;
import com.platform.account.v1.AccountResponse;
import com.platform.account.v1.AccountServiceGrpc;
import com.platform.account.v1.UpdateAccountRequest;
import io.grpc.Status;
import io.grpc.stub.StreamObserver;

import java.util.Optional;

public class AccountServiceImpl extends AccountServiceGrpc.AccountServiceImplBase {

    private final AccountRepository accountRepository;

    public AccountServiceImpl(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    @Override
    public void updateAccount(UpdateAccountRequest request, StreamObserver<AccountResponse> responseObserver) {
        if (request.getAccountId() == null || request.getAccountId().isBlank()) {
            responseObserver.onError(
                Status.INVALID_ARGUMENT
                    .withDescription("account_id must not be empty")
                    .asRuntimeException()
            );
            return;
        }

        Optional<Account.Status> newStatus;
        Optional<String> newDisplayName;
        try {
            newStatus = AccountMapper.toDomainStatus(request);
            newDisplayName = AccountMapper.toDomainDisplayName(request);
        } catch (IllegalArgumentException ex) {
            responseObserver.onError(
                Status.INVALID_ARGUMENT
                    .withDescription(ex.getMessage())
                    .asRuntimeException()
            );
            return;
        }

        Optional<Account> existingOpt = accountRepository.findById(request.getAccountId());
        if (existingOpt.isEmpty()) {
            responseObserver.onError(
                Status.NOT_FOUND
                    .withDescription("Account with ID " + request.getAccountId() + " not found")
                    .asRuntimeException()
            );
            return;
        }

        Account updatedAccount = existingOpt.get().copyWith(newStatus, newDisplayName);
        Account persisted = accountRepository.save(updatedAccount);

        AccountResponse response = AccountMapper.toProtoResponse(persisted);
        responseObserver.onNext(response);
        responseObserver.onCompleted();
    }
}
