Here is the plan and implementation for migrating the legacy `UserController` REST endpoints to the `UserService` gRPC service, adhering to the proto-first contract and layered architecture patterns.

---

### Migration Plan

1. **Service Interface & Layering:**
   - Define the gRPC server implementation struct (`UserServiceServer`) embedding the generated proto interface.
   - Inject the core domain `UserService` / repository layer into the gRPC handler.
2. **Defensive Error Handling:**
   - Map domain errors to standard gRPC status codes (`codes.InvalidArgument`, `codes.NotFound`, `codes.Internal`, etc.) using `google.golang.org/grpc/status`.
3. **Endpoint Translation:**
   - `GET /users/:id` $\rightarrow$ `GetUser(ctx, *pb.GetUserRequest) (*pb.GetUserResponse, error)`
   - `POST /users` $\rightarrow$ `CreateUser(ctx, *pb.CreateUserRequest) (*pb.CreateUserResponse, error)`
   - `PUT /users/:id` $\rightarrow$ `UpdateUser(ctx, *pb.UpdateUserRequest) (*pb.UpdateUserResponse, error)`
   - `DELETE /users/:id` $\rightarrow$ `DeleteUser(ctx, *pb.DeleteUserRequest) (*pb.DeleteUserResponse, error)`
4. **Memory Bank Update:**
   - Synchronize `activeContext.md` and `progress.md`.

---

### Implementation

#### 1. gRPC Server Implementation (`internal/delivery/grpc/user_service.go`)

```go
package grpc

import (
	"context"
	"errors"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"yourproject/internal/domain"
	pb "yourproject/proto/gen/go/user"
)

type UserGRPCHandler struct {
	pb.UnimplementedUserServiceServer
	domainService domain.UserService
}

func NewUserGRPCHandler(svc domain.UserService) *UserGRPCHandler {
	return &UserGRPCHandler{
		domainService: svc,
	}
}

func (h *UserGRPCHandler) GetUser(ctx context.Context, req *pb.GetUserRequest) (*pb.GetUserResponse, error) {
	if req.GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user id is required")
	}

	user, err := h.domainService.GetByID(ctx, req.GetId())
	if err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			return nil, status.Errorf(codes.NotFound, "user %s not found", req.GetId())
		}
		return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
	}

	return &pb.GetUserResponse{
		User: &pb.User{
			Id:        user.ID,
			Email:     user.Email,
			Name:      user.Name,
			CreatedAt: user.CreatedAt.Unix(),
		},
	}, nil
}

func (h *UserGRPCHandler) CreateUser(ctx context.Context, req *pb.CreateUserRequest) (*pb.CreateUserResponse, error) {
	if req.GetEmail() == "" || req.GetName() == "" {
		return nil, status.Error(codes.InvalidArgument, "name and email are required")
	}

	createdUser, err := h.domainService.Create(ctx, domain.CreateUserDTO{
		Email: req.GetEmail(),
		Name:  req.GetName(),
	})
	if err != nil {
		if errors.Is(err, domain.ErrAlreadyExists) {
			return nil, status.Errorf(codes.AlreadyExists, "user with email %s already exists", req.GetEmail())
		}
		return nil, status.Errorf(codes.Internal, "failed to create user: %v", err)
	}

	return &pb.CreateUserResponse{
		User: &pb.User{
			Id:        createdUser.ID,
			Email:     createdUser.Email,
			Name:      createdUser.Name,
			CreatedAt: createdUser.CreatedAt.Unix(),
		},
	}, nil
}

func (h *UserGRPCHandler) UpdateUser(ctx context.Context, req *pb.UpdateUserRequest) (*pb.UpdateUserResponse, error) {
	if req.GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user id is required")
	}

	updatedUser, err := h.domainService.Update(ctx, req.GetId(), domain.UpdateUserDTO{
		Name:  req.GetName(),
		Email: req.GetEmail(),
	})
	if err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			return nil, status.Errorf(codes.NotFound, "user %s not found", req.GetId())
		}
		return nil, status.Errorf(codes.Internal, "failed to update user: %v", err)
	}

	return &pb.UpdateUserResponse{
		User: &pb.User{
			Id:        updatedUser.ID,
			Email:     updatedUser.Email,
			Name:      updatedUser.Name,
			CreatedAt: updatedUser.CreatedAt.Unix(),
		},
	}, nil
}

func (h *UserGRPCHandler) DeleteUser(ctx context.Context, req *pb.DeleteUserRequest) (*pb.DeleteUserResponse, error) {
	if req.GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user id is required")
	}

	err := h.domainService.Delete(ctx, req.GetId())
	if err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			return nil, status.Errorf(codes.NotFound, "user %s not found", req.GetId())
		}
		return nil, status.Errorf(codes.Internal, "failed to delete user: %v", err)
	}

	return &pb.DeleteUserResponse{Success: true}, nil
}
